{
  "implementation": "def solve(case):
    payload = case['payload']
    round_scores = payload['round_scores']
    round_targets = payload['round_targets']
    forced = payload.get('forced', [])
    if not isinstance(round_scores, list) or not isinstance(round_targets, list):
        raise ValueError("round_scores and round_targets must be lists")
    num_rounds = len(round_scores)
    if len(round_targets) != num_rounds:
        raise ValueError("round_targets length must match round_scores")
    if num_rounds == 0:
        return {"masks": [], "final": []}
    n = len(round_scores[0])
    for scores in round_scores:
        if len(scores) != n:
            raise ValueError("All round_scores must have same length")
    for f in forced:
        if not isinstance(f, int) or f < 0 or f >= n:
            raise ValueError("Forced index out of range")
    active = list(range(n))
    masks = []
    for i in range(num_rounds):
        scores = round_scores[i]
        target = round_targets[i]
        if target < 0:
            raise ValueError("Target must be non-negative")
        forced_in_round = [f for f in forced if f in active]
        if len(forced_in_round) > target:
            raise ValueError(f"Forced count {len(forced_in_round)} exceeds target {target} in round {i}")
        if target > len(active):
            raise ValueError(f"Target {target} exceeds active count {len(active)} in round {i}")
        # sort active by descending score, ties by ascending index
        active_sorted = sorted(active, key=lambda idx: (-scores[idx], idx))
        selected_set = set(forced_in_round)
        for idx in active_sorted:
            if len(selected_set) == target:
                break
            if idx not in selected_set:
                selected_set.add(idx)
        # preserve original order: sort selected indices ascending
        new_active = sorted(selected_set)
        masks.append(list(new_active))
        active = new_active
    return {"masks": masks, "final": active}"
}
